import { createPrivateWeakStore } from "../../security/private-weak-store.js";
import { SpanKind, SpanStatusCode, } from "./api-shim.js";
import { getProjectTraceProvider } from "./project-trace-scope.js";
import { ContextPropagation } from "./context-propagation.js";
import { SpanOperations } from "./span-operations.js";
const helpers = createPrivateWeakStore();
/** Public application helpers reuse the existing sanitization/finalization behavior. */
export function getProjectTraceHelpers(provider = getProjectTraceProvider()) {
    if (!provider)
        return undefined;
    let cached = helpers.get(provider);
    if (cached)
        return cached;
    const trace = provider.getTraceAPI();
    const propagator = provider.getPropagator();
    const api = {
        trace: {
            getTracer: (name, version) => provider.getProvider().getTracer(name ?? "application", version),
            setSpan: (ctx, span) => trace.setSpan(ctx, span),
        },
        context: provider.getContextAPI(),
        propagation: {
            setGlobalPropagator() { },
            extract: (ctx, carrier) => propagator.extract(ctx, carrier, {
                keys: Object.keys,
                get: (record, key) => record[key],
            }),
            inject: (ctx, carrier) => propagator.inject(ctx, carrier, {
                set: (record, key, value) => {
                    record[key] = value;
                },
            }),
        },
        SpanKind,
        SpanStatusCode,
    };
    cached = {
        spans: new SpanOperations(api, api.trace.getTracer("veryfront.application")),
        context: new ContextPropagation(api, propagator),
    };
    helpers.set(provider, cached);
    return cached;
}
